#include <iostream>

int doble_entero(int valor) {
    return valor * 2;
}

double doble_real(double valor) {
    return valor * 2;
}

int main() {
    const double dato = 3.5;
    const int entero = doble_entero(static_cast<int>(dato));
    const double real = doble_real(dato);
    std::cout << entero << " " << real;
    return 0;
}

